import React, { useState, useEffect, useRef } from "react";
import { Link } from "react-scroll";
import "./Navbar.css"; // Importa el archivo de estilos

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false); // Estado para controlar el menú hamburguesa
  const menuRef = useRef(null); // Referencia al menú
  const menuIconRef = useRef(null); // Referencia al ícono del menú

  const toggleMenu = () => setIsOpen(!isOpen);

  const closeMenu = () => setIsOpen(false); // Función para cerrar el menú

  // Detectar clic fuera del menú para cerrarlo
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        menuRef.current && !menuRef.current.contains(event.target) && 
        menuIconRef.current && !menuIconRef.current.contains(event.target)
      ) {
        closeMenu(); // Cerrar el menú si el clic es fuera del menú o el ícono
      }
    };

    // Agregar el evento de clic global
    document.addEventListener("mousedown", handleClickOutside);

    // Limpiar el evento cuando el componente se desmonte
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <h1 className="logo">
          <Link to="home" offset={-70}>FREE TRADER'S</Link>
        </h1>

        {/* Menú hamburguesa con iconos de FontAwesome */}
        <div
          ref={menuIconRef} // Referencia para el ícono
          className={`menu-icon ${isOpen ? "open" : ""}`}
          onClick={toggleMenu}
        >
          <i className={`fa-solid ${isOpen ? "fa-xmark" : "fa-bars"}`} aria-hidden="true"></i>
        </div>

        {/* Enlaces de navegación */}
        <ul ref={menuRef} className={`nav-links ${isOpen ? "active" : ""}`}>
          <li><Link to="home" smooth={true} duration={500} onClick={closeMenu} offset={-50}>Inicio</Link></li>
          <li><Link to="cursos" smooth={true} duration={500} onClick={closeMenu} offset={-90}>Cursos</Link></li>
          <li><Link to="sobre-nosotros" smooth={true} duration={500} onClick={closeMenu} offset={-70}>Sobre Nosotros</Link></li>
          <li><Link to="contacto" smooth={true} duration={500} onClick={closeMenu} offset={-70}>Contacto</Link></li>
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
